/**
 * Activity-feed line builders for /radar/[searchId].
 *
 * Status lines for /radar. These must not claim a partner network,
 * outside shelters, volunteers, or community sightings. Real comparisons
 * against this shelter's public animals render in RosterMatchPanel.
 *
 * Feed ids are generated by the caller (a per-mount ref counter in
 * RadarView) and passed in explicitly, so builders stay pure and no
 * module-level mutable state is needed.
 */

import { CheckCircle2, Heart, MapPin, PawPrint, Radio, ShieldCheck, X } from "lucide-react";

import type { SearchStatus, TrFn } from "./types";

export interface FeedEntry {
  id: string;
  text: string;
  createdAtLabel: string;
  icon: typeof ShieldCheck;
}

const FEED_BANK: {
  icon: typeof ShieldCheck;
  text: (tr: TrFn) => string;
}[] = [
  {
    icon: Radio,
    text: (tr) => tr("radar.feed_queued"),
  },
  {
    icon: ShieldCheck,
    text: (tr) => tr("radar.feed_demo"),
  },
  {
    icon: MapPin,
    text: (tr) => tr("radar.feed_network"),
  },
  {
    icon: PawPrint,
    text: (tr) => tr("radar.feed_validated"),
  },
  {
    icon: Heart,
    text: (tr) => tr("radar.feed_share_hint"),
  },
  {
    icon: Radio,
    text: (tr) => tr("radar.feed_no_sightings"),
  },
];

function pick<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

function nowLabel(): string {
  return new Date().toLocaleTimeString(undefined, { timeStyle: "short" });
}

export function buildInitialFeed(tr: TrFn, id: string): FeedEntry[] {
  return [
    {
      id,
      text: tr("radar.feed_initial"),
      createdAtLabel: nowLabel(),
      icon: ShieldCheck,
    },
  ];
}

export function buildNextFeed(tr: TrFn, id: string): FeedEntry {
  const bank = pick(FEED_BANK);
  return {
    id,
    text: bank.text(tr),
    createdAtLabel: nowLabel(),
    icon: bank.icon,
  };
}

/** The single honest line appended when the owner closes the search. */
export function buildClosedFeedEntry(
  status: Exclude<SearchStatus, "SEARCHING">,
  tr: TrFn,
  id: string,
): FeedEntry {
  return {
    id,
    text:
      status === "FOUND"
        ? tr("radar.closed_found")
        : tr("radar.closed_cancelled"),
    createdAtLabel: nowLabel(),
    icon: status === "FOUND" ? CheckCircle2 : X,
  };
}
